function sanitizeRedirectPath(rawRedirect, fallback = "/account") {
	if (typeof rawRedirect !== "string") return fallback;
	const trimmed = rawRedirect.trim();
	if (!trimmed) return fallback;
	if (!trimmed.startsWith("/") || trimmed.startsWith("//") || trimmed.startsWith("/\\")) return fallback;
	if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/i.test(trimmed)) return fallback;
	if (trimmed.includes("\r") || trimmed.includes("\n")) return fallback;
	return trimmed;
}
function validatePasswordStrength(password, lang = "mr") {
	const raw = typeof password === "string" ? password : "";
	const checks = {
		minLength: raw.length >= 8 && raw.length <= 128,
		hasUppercase: /[A-Z]/.test(raw),
		hasLowercase: /[a-z]/.test(raw),
		hasNumber: /\d/.test(raw),
		hasSpecial: /[^A-Za-z0-9]/.test(raw)
	};
	let passedCount = 0;
	if (checks.minLength) passedCount++;
	if (checks.hasUppercase && checks.hasLowercase) passedCount++;
	if (checks.hasNumber) passedCount++;
	if (checks.hasSpecial) passedCount++;
	const score = Math.min(4, Math.max(0, passedCount));
	const labelsMr = [
		"अत्यंत कमकुवत",
		"कमकुवत",
		"साधारण",
		"चांगला",
		"अतिशय सुरक्षित"
	];
	const labelsEn = [
		"Very Weak",
		"Weak",
		"Fair",
		"Strong",
		"Very Strong"
	];
	const isValid = checks.minLength && checks.hasUppercase && checks.hasLowercase && checks.hasNumber && checks.hasSpecial;
	let error;
	if (!isValid) error = lang === "mr" ? "पासवर्ड किमान ८ अक्षरांचा असावा आणि त्यात मोठे अक्षर (A-Z), लहान अक्षर (a-z), अंक (0-9) व विशेष चिन्ह (@#$!) असणे आवश्यक आहे." : "Password must be at least 8 characters and include uppercase, lowercase, a number, and a special character.";
	return {
		isValid,
		score,
		label: lang === "mr" ? labelsMr[score] : labelsEn[score],
		error,
		checks
	};
}
